package com.bettertoppi.topuhud.hud;
import com.bettertoppi.topuhud.modmenu.TopuUtilityManager;import net.fabricmc.fabric.api.client.event.lifecycle.v1.ClientTickEvents;import net.fabricmc.fabric.api.client.rendering.v1.HudRenderCallback;import net.minecraft.client.MinecraftClient;import net.minecraft.client.gui.DrawContext;import net.minecraft.text.Text;import net.minecraft.entity.player.PlayerEntity;import java.util.Locale;
public final class TopuUtilityHud{private static int jumps;private static boolean ground=true;private TopuUtilityHud(){}public static void initialize(){ClientTickEvents.END_CLIENT_TICK.register(c->{if(c.player!=null){if(!c.player.isOnGround()&&ground)jumps++;ground=c.player.isOnGround();}});HudRenderCallback.EVENT.register((d,t)->render(MinecraftClient.getInstance(),d));}private static boolean on(String id){for(TopuUtilityManager.Utility u:TopuUtilityManager.ALL)if(u.id().equals(id))return TopuUtilityManager.isEnabled(u);return false;}private static void render(MinecraftClient c,DrawContext d){if(c.player==null||c.world==null)return;PlayerEntity p=c.player;int x=Math.max(4,c.getWindow().getScaledWidth()-220),y=8;String[] a={on("coordinates")?"XYZ: "+p.getBlockX()+", "+p.getBlockY()+", "+p.getBlockZ():null,on("direction")?"Direction: "+p.getHorizontalFacing().asString().toUpperCase(Locale.ROOT):null,on("speed")?String.format(Locale.ROOT,"Speed: %.2f",Math.sqrt(p.getVelocity().x*p.getVelocity().x+p.getVelocity().z*p.getVelocity().z)*20):null,on("jumpcount")?"Jumps: "+jumps:null,on("sprintstatus")?"Sprint: "+(p.isSprinting()?"ON":"OFF"):null,on("velocity")?String.format(Locale.ROOT,"Velocity: %.2f %.2f %.2f",p.getVelocity().x,p.getVelocity().y,p.getVelocity().z):null,on("helditem")?"Held: "+p.getMainHandStack().getName().getString():null};for(String s:a)if(s!=null){d.drawTextWithShadow(c.textRenderer,Text.literal(s),x,y,0xFFE7EDF7);y+=12;}}}
